  ('schdassln', 'schdassln', '', '', '', '', 'stasseln', '[{"kategorie": "wörtlich", "text": "\"stößeln\" (vom mittelhochdeutschen \"stöȝen\"=\"stößeln\")"}, {"kategorie": "allg.", "text": "stapeln, schlichten, zu einem Stoß aufschichten (Spielkarten, Zeitungen, etc.)"}, {"kategorie": "Gaunersprache", "text": "etwas stehlen, klauen, entwenden"}]'::jsonb, ''),
