  ('schdaum', 'schdaum', '', '', '', '', 'stauben', '[{"kategorie": "wörtlich", "text": "\"Staub von sich geben\" bzw. \"stäuben\" (vom althochdeutschen \"stouben\"=\"stauben\" bzw. \"stäuben\")"}, {"kategorie": "allg.", "text": "stieben, wirbeln, hochwirbeln (Schnee, etc.)"}, {"kategorie": "Küchenjargon", "text": "mit Mehl bestreuen, \"bemehlen\", eindicken (Suppe, etc.)"}, {"kategorie": "scherzhaft für", "text": "eine Zigarette rauchen, paffen, schmauchen"}, {"kategorie": "fig.", "text": "jemanden/etwas überholen, abhängen, \"abstauben\", hinter sich lassen"}, {"kategorie": "scherzhaft für", "text": "\"den Staub hinunterschwemmen\", trinken, saufen, seinen Durst löschen"}]'::jsonb, ''),
