  ('schdaubwuckerl', 'Schdaubwuckerl', '', '', '', '', 'Staubwuckerl', '[{"kategorie": "wörtlich", "text": "\"Staubfusselchen\" (Determinativkompositum aus \"Staub\"=\"Schmutz\" und [[Waukerl]]=\"Fusselchen\")"}, {"kategorie": "allg.", "text": "Staubpartikelchen, Staubfädchen, Staubknäuelchen, [[Staubwuckerl]]"}]'::jsonb, ''),
