  ('schdaudnrauschn', 'Schdaudnrauschn', '', '', '', '', 'Staudenrauschen', '[{"kategorie": "wörtlich", "text": "\"Rauschen im Gebüsch\""}, {"kategorie": "scherzhaft für", "text": "\"rauschender Sex hinter der Staude\", \"rauschender Busch-Sex\", \"rauschendes Unterholz-Rendezvous\""}]'::jsonb, ''),
  ('schdeckal', 'Schdeckal', '', '', '', '', 'Steckerl', '[{"kategorie": "wörtlich", "text": "\"kleiner [[Stecken]]\""}, {"kategorie": "", "text": "Stöckchen, Apportierstöckchen (für Hunde)"}, {"kategorie": "", "text": "Rohrstock, Holzstock, [[Staberl]]"}]'::jsonb, ''),
  ('kokolores', 'Kokolores!', '', '', '', '', 'Kokolores!', '[{"kategorie": "wörtlich", "text": "Unsinn!  2. (Ausruf und herablassende Reaktion auf einen dummen Sager): Quatsch!  Firlefanz!  Papperlapapp! [[Schdeckal]] in Oasch! (Zur Erkärung: Der Begriff \"Kokolores\" stammt ursprünglich aus der Drogenszene: Die Einnahme von Kokain löst bekanntermaßen verstärkten Redefluss bei den Junkies aus und lässt sie unsinniges Zeug ohne Unterlass daherreden)"}]'::jsonb, ''),
  ('schdeckalfisch', 'Schdeckalfisch', '', '', '', '', 'Steckerlfisch', '[{"kategorie": "wörtlich", "text": "\"Fisch am Holzspieß\""}, {"kategorie": "", "text": "Grillfisch, Bratfisch (Fisch, der auf ein Steckerl [Holzstäbchen] gespießt und über offenem Feuer gebraten wird)"}]'::jsonb, ''),
  ('schdeffi', 'Schdeffi', '', '', '', '', 'Steffi', '[{"kategorie": "", "text": "Stefanie (weiblicher Vorname)"}]'::jsonb, ''),
  ('schdeffae', 'Schdeffä', '', '', '', '', 'Steffl', '[{"kategorie": "wörtlich, Koseform für", "text": "Stefan (männlicher Vorname)"}, {"kategorie": "Kosename für den", "text": "[[Wiener]] Stephansdom (Wahrzeichen von Wien)"}]'::jsonb, ''),
  ('koimoakt', 'Koimoakt', '', '', '', '', 'Kohlmarkt', '[{"kategorie": "allg", "text": ". \"exklusive und historische Einkaufsstraße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Sie zählt zu den bekanntesten und elegantesten Straßen Wiens und verbindet den [[Michaelerplatz]] mit dem [[Graben]] im Herzen des Wiener Stadtzentrums"}, {"kategorie": "", "text": "Der Name \"Kohlmarkt\" geht auf das Mittelalter zurück, als in dieser Gegend ein Markt für den Verkauf von Holzkohle stattfand, die damals ein wichtiger Brennstoff für die Stadtbewohner war. Dieser Kohlenmarkt entwickelte sich im Laufe der Zeit zu einem zentralen Handelsplatz, und mit der Nähe zur Hofburg, der Residenz der Habsburger, wurde der Kohlmarkt zunehmend zu einer feinen Einkaufsstraße, die den Adel und die wohlhabende Wiener Bürgerschaft anzog"}, {"kategorie": "", "text": "Im 18. und 19. Jahrhundert wurde der Kohlmarkt zu einer beliebten Adresse für luxuriöse Geschäfte, darunter Goldschmiede, Juweliere und Schneider, die sowohl die Wiener Oberschicht als auch den kaiserlichen Hof belieferten. Der Kohlmarkt erlebte in dieser Zeit seine Blüte als eine der vornehmsten Straßen der Stadt"}, {"kategorie": "", "text": "Die Gebäude am Kohlmarkt spiegeln den historischen Charme und die architektonische Pracht Wiens wider. Viele der Bauten stammen aus dem 19. Jahrhundert und sind im Historismus oder im Stil des Barock gehalten, was der Straße eine eindrucksvolle Eleganz verleiht"}, {"kategorie": "", "text": "Eine der bekanntesten Sehenswürdigkeiten am Kohlmarkt ist die Demel-Konditorei, eine traditionelle Wiener Konditorei und Kaffeehaus, das 1786 gegründet wurde und früher kaiserlicher Hoflieferant war"}, {"kategorie": "", "text": "Heute ist der Kohlmarkt vor allem als Luxus-Einkaufsstraße bekannt. Internationale Luxusmarken wie Louis Vuitton, Cartier, Chanel und viele andere haben hier exklusive Geschäfte, die Mode, Schmuck, Uhren und Accessoires der gehobenen Preisklasse anbieten. Zusammen mit dem Graben und der Kärntner Straße bildet der Kohlmarkt das [[Goldene U]], die edelste Einkaufsgegend Wiens"}]'::jsonb, ''),
  ('michaelaplotz', 'Michaelaplotz', '', '', '', '', 'Michaelerplatz', '[{"kategorie": "allg", "text": "einer der bedeutendsten historischen Plätze in Wien, gelegen im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Er ist ein zentraler Knotenpunkt im historischen Zentrum (Straßenkreuzung am Schnittpunkt von [[Herrengasse]], [[Kohlmarkt]] und [[Reitschulgasseund]]) und ist umgeben von wichtigen Sehenswürdigkeiten und architektonischen Wahrzeichen, die tief in der Geschichte Wiens verwurzelt sind"}, {"kategorie": "", "text": "Der Platz wird dominiert von der eindrucksvollen Fassade des Michaelertrakts der Hofburg, die im Stil des Barock und [[Klassizismus]] gestaltet ist. Diese monumentale Architektur vermittelt einen Eindruck von der Pracht und Macht der Habsburger Monarchie"}, {"kategorie": "", "text": "In der Mitte des Michaelerplatzes befinden sich freigelegte Reste römischer und mittelalterlicher Siedlungen. Diese archäologischen Ausgrabungen geben einen Einblick in die frühe Geschichte Wiens und sind ein wichtiges Zeugnis für die lange Besiedlungsgeschichte des Platzes"}, {"kategorie": "", "text": "Der Michaelerplatz war über Jahrhunderte hinweg ein Zentrum des höfischen Lebens in Wien. Er diente als repräsentativer Raum für kaiserliche Auftritte und Veranstaltungen und war ein Ort, an dem sich die Macht und der Einfluss der Habsburger Dynastie manifestierten."}]'::jsonb, ''),
  ('michaelakiachn', 'Michaelakiachn', '', '', '', '', 'Miachaelerkirche', '[{"kategorie": "allg.", "text": "\"eine der ältesten und bedeutendsten Kirchen in Wien\" (offizieller Name: \"Kirche St. Michael zu den Engeln\")"}, {"kategorie": "", "text": "Sie liegt am [[Michaelerplatz]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), direkt gegenüber der [[Hofburg]], dem ehemaligen Kaiserpalast der Habsburger"}, {"kategorie": "", "text": "Die Michaelerkirche wurde ursprünglich im 13. Jahrhundert im romanischen Stil erbaut und war über Jahrhunderte hinweg eine der bedeutendsten Pfarrkirchen Wiens. Sie war eng mit der kaiserlichen Familie verbunden, da sie unmittelbar vor dem Haupttor der Hofburg liegt und oft für königliche Zeremonien genutzt wurde"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte wurde die Kirche mehrfach umgebaut und erweitert, wobei sie gotische, barocke und klassizistische Elemente aufnahm. Die heutige Fassade, die im klassizistischen Stil gehalten ist, stammt aus dem 18. Jahrhundert"}, {"kategorie": "", "text": "Ein markantes Merkmal der Kirche ist der 82 Meter hohe Glockenturm, der die Silhouette des Michaelerplatzes prägt. Zudem beherbergt die Kirche eine der ältesten Orgeln Wiens, die sogenannte \"Wöckherl-Orgel\", die um 1714 von Johann David Sieber gebaut wurde und als eine der wertvollsten historischen Orgeln Europas gilt."}]'::jsonb, ''),
  ('looshaus', 'Looshaus', '', '', '', '', 'Looshaus', '[{"kategorie": "allg.", "text": "\"ikonisches Bauwerk am [[Michaelerplatz]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), direkt gegenüber der [[Hofburg]]\""}, {"kategorie": "", "text": "Das Looshaus ist eines der frühesten und wichtigsten Beispiele der modernen Wiener Architektur und ein symbolträchtiges Beispiel für den Bruch mit traditionellen Stilen. Es wurde von Adolf Loos, einem der einflussreichsten Architekten der Wiener Moderne, entworfen und zwischen 1909 und 1911 erbaut. Loos war ein prominenter Vertreter des Funktionalismus und ein scharfer Kritiker des damals vorherrschenden [[Historismus]] und Jugendstils.  3. Das Looshaus zeichnet sich durch seine klare, nüchterne Fassade aus, die im Gegensatz zu den dekorativen und ornamentalen Fassaden der umliegenden Gebäude steht. Loos verzichtete bewusst auf den damals üblichen Fassadenschmuck und setzte stattdessen auf einfache, rechteckige Fenster und glatte Flächen, was dem Gebäude ein modernes und minimalistisches Erscheinungsbild verleiht"}, {"kategorie": "", "text": "Bei seiner Errichtung stieß das Looshaus auf heftige Kritik (vor allem wegen seines radikalen Bruchs mit den architektonischen Traditionen) und wurde von der Wiener Bevölkerung und den Medien zunächst als \"Haus ohne Augenbrauen\" verspottet, da die Fenster keine Gesimse oder dekorativen Verzierungen aufwiesen, wie es damals üblich war."}]'::jsonb, ''),
  ('heangossn', 'Heangossn', '', '', '', '', 'Herrengasse', '[{"kategorie": "allg.", "text": "prominente Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die vom [[Michaelerplatz]] bis zur [[Freyung]] verläuft"}, {"kategorie": "", "text": "Die Herrengasse war bereits im Mittelalter eine wichtige Straße in Wien. Sie erhielt ihren Namen, weil sich hier zahlreiche Paläste des Adels, der sogenannten \"Herren\", befanden. Diese Aristokraten besaßen hier Stadtpalais, die sie während ihres Aufenthalts in der Stadt nutzten, insbesondere während der Sitzungen des Reichstages"}]'::jsonb, ''),
  ('reitschuigossn', 'Reitschuigossn', '', '', '', '', 'Reitschulgasse', '[{"kategorie": "allg.", "text": "\"Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), ehemals \"Hochstraße\", 1862 umbenannt nach dem dort befindlichen Gebäude der Winterreitschule"}, {"kategorie": "heute", "text": "Die Reitschulgasse erhielt ihren Namen von der kaiserlichen Reitschule, die in der Nähe der Hofburg angesiedelt war. Diese Reitschule war Teil der [[Spanischen]] Hofreitschule, einer der ältesten und renommiertesten Reitschulen der Welt, die für ihre klassische Reitkunst berühmt ist"}, {"kategorie": "", "text": "Die Reitschulgasse liegt zentral in der Wiener Altstadt, nur wenige Schritte von bedeutenden historischen und kulturellen Stätten entfernt (darunter die [[Hofburg]], die [[Albertina]], die [[Augustinerkirche]] und der [[Michaelerplatz]]) und ist heute eine Flaniermeile in der Wiener Innenstadt, die sich wie ein malerischer Fluss durch die Altstadt schlängelt, gesäumt von historischen Gebäuden (überwiegend aus dem 18. und 19. Jahrhundert, Mischung aus barocken und klassizistischen Stilelementen) sowie belebten Straßencafés"}]'::jsonb, ''),
  ('freyung', 'Freyung', '', '', '', '', 'Freyung', '[{"kategorie": "allg.", "text": "\"großer, prunkvoller Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), \"der Platz vor der [[Schottenkirche]]\", der im 12. Jahrundert noch außerhalb der [[Stadtmauer]] lag"}, {"kategorie": "", "text": "Die Freyung ist einer der bedeutendsten und traditionsreichsten Plätze in der Wiener Altstadt und hat eine lange Geschichte, die bis ins Mittelalter zurückreicht"}, {"kategorie": "", "text": "Der Name \"Freyung\" erklärt sich aus der 1181 verfügten Befreiung des Klosterbezirks von der städtischen Gerichtsbarkeit. Die Freyung war ursprünglich ein Bereich, der dem [[Schottenstift]] zugehörte, einer Abtei, die von irischen (skotischen) Mönchen gegründet wurde. Dieser Ort gewährte im Mittelalter Immunität vor der städtischen Gerichtsbarkeit"}, {"kategorie": "heute", "text": "Die Freyung in Wien strahlt mit ihren barocken Palais"}]'::jsonb, ''),
  ('augustinagossn', 'Augustinagossn', '', '', '', '', 'Augustinergasse', '[{"kategorie": "hist.", "text": "historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft parallel zur [[Reitschulgasse]] und verbindet den [[Albertinaplatz]] mit dem [[Josefsplatz]], zwei bedeutenden Plätzen in der Wiener Altstadt"}, {"kategorie": "", "text": "Die Augustinergasse ist nach der [[Augustinerkirche]] benannt, die eines der bedeutendsten Gebäude entlang dieser Straße ist;  Die Augustinergasse ist Teil der alten \"Hochstraße\" (römische Limesstraße, die sich ursprünglich zwischen [[Schottengasse]] und [[Kärntner]] Straße erstreckte)"}, {"kategorie": "heute", "text": "Augustinerstraße (beginnt heute beim [[Albertinaplatz]] neben der [[Augustinerbastei]] und endet im Norden beim [[Josefsplatz]] beim [[Palais]] Palffy nach der Abzweigung der [[Dorotheergasse]]"}, {"kategorie": "", "text": "Der Name der Augustinerstraße geht auf die Kirche und das Kloster gleichen Namens zurück. Heute bildet sie einen lebendigen Flur durch die Jahrhunderte, flankiert von eleganten Geschäften und traditionellen Wiener Kaffeehäusern"}]'::jsonb, ''),
  ('augustinakiachn', 'Augustinakiachn', '', '', '', '', 'Augustinerkirche', '[{"kategorie": "hist.", "text": "\"bedeutende Kirche im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), offiziell \"Kirche St. Augustin\""}, {"kategorie": "", "text": "Sie liegt am [[Augustinerplatz]], in unmittelbarer Nähe zur [[Hofburg]] und zur [[Albertina]], und gehört zu den ältesten und historisch wichtigsten Kirchen der Stadt"}, {"kategorie": "", "text": "Die Augustinerkirche wurde im 14. Jahrhundert (1327-1339) im Auftrag von Herzog Friedrich dem Schönen als Klosterkirche für die Augustiner-Eremiten erbaut. Sie wurde bald zur Hofkirche der Habsburger und spielte eine zentrale Rolle im religiösen und gesellschaftlichen Leben am Wiener Hof"}, {"kategorie": "", "text": "Aufgrund ihrer Nähe zur Hofburg war die Augustinerkirche der Schauplatz vieler kaiserlicher Hochzeiten und anderer bedeutender Zeremonien, darunter die Eheschließungen von [[Kaiser]] Franz Joseph I. und Elisabeth ([[Sisi]]) sowie [[Napoleon]] Bonapartes Hochzeit mit Marie-Louise von Österreich (per Stellvertreter)"}, {"kategorie": "", "text": "Die Kirche ist überwiegend im gotischen Stil erbaut und zeichnet sich durch eine schlichte, aber beeindruckende Architektur aus. Die Fassade ist eher unauffällig, aber das Innere der Kirche besticht durch hohe, spitzbogige Fenster und ein prachtvolles gotisches [[Gewölbe]]. Die Kirche besitzt keinen eigenen Turm; stattdessen teilt sie sich den Turm mit der angrenzenden Hofburg, was ihre enge Verbindung mit dem Kaiserhof unterstreicht"}, {"kategorie": "", "text": "Im Inneren der Kirche befindet sich das berühmte Grabmal der Erzherzogin Maria Christina, das von dem Bildhauer Antonio Canova geschaffen wurde. Das klassizistische Monument ist eines der herausragendsten Kunstwerke der Kirche und zieht viele Besucher an. Die Kirche ist auch bekannt für die [[Herzgruft]], in der die Herzen von 54 Mitgliedern der Habsburger Dynastie beigesetzt sind. Diese Tradition begann im 17. Jahrhundert und unterstreicht die enge Verbindung der Kirche mit der Habsburger Familie"}, {"kategorie": "", "text": "Die Augustinerkirche ist für ihre musikalischen Aufführungen bekannt. Die Kirchenmusik spielt eine zentrale Rolle in den Gottesdiensten, und es werden regelmäßig Messen mit musikalischer Begleitung von Komponisten wie Mozart, Haydn und Beethoven aufgeführt. Außerdem verfügt die Kirche über eine bedeutende Orgel, die regelmäßig für Konzerte genutzt wird."}]'::jsonb, ''),
  ('teinfoitgossn', 'Teinfoitgossn', '', '', '', '', 'Teinfaltgasse', '[{"kategorie": "hist.", "text": "historisch gewachsene Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft parallel zum [[Ring]] und verbindet den [[Schottenring]] mit der [[Herrengasse]], zwei bedeutenden Straßen im historischen Zentrum Wiens"}, {"kategorie": "", "text": "Die Teinfaltgasse ist nach einem alten Wiener Bürger namens Paul Teinfalt benannt, der im 17. Jahrhundert in Wien lebte, über den aber sonst nichts Näheres bekannt ist"}, {"kategorie": "", "text": "Die Teinfaltgasse ist von historischen Gebäuden gesäumt, die oft architektonisch bedeutsam sind. Die meisten Gebäude stammen aus dem 19. Jahrhundert und spiegeln den Stil der [[Gründerzeit]] wider. Die Architektur entlang der Teinfaltgasse ist typisch für das historische Wien und zeigt eine Mischung aus Wohn- und Geschäftsbauten"}]'::jsonb, ''),
  ('groom', 'Groom', '', '', '', '', 'Graben', '[{"kategorie": "allg.", "text": "\"eine der bekanntesten und historisch bedeutendsten Straßen in der Wiener Innenstadt, im 1. Wiener Gemeindebezirk ([[Innere]] Stadt\")"}, {"kategorie": "", "text": "Er befindet sich im Herzen der Stadt und ist heute eine exklusive Einkaufsstraße sowie ein beliebter Treffpunkt für Einheimische und Touristen"}, {"kategorie": "", "text": "Der Name \"Graben\" stammt von einem frühmittelalterlichen Graben, der in der Römerzeit als Teil der Befestigungsanlagen des römischen Lagers [[Vindobona]] diente. Der Graben verlief ursprünglich entlang dieser Befestigungen und wurde im Mittelalter zugeschüttet, um Platz für eine breite Straße zu schaffen"}, {"kategorie": "", "text": "Im Mittelalter entwickelte sich der Graben zu einer wichtigen Markt- und Handelsstraße. Hier wurden Waren aller Art gehandelt, und der Graben wurde zu einem zentralen Punkt im wirtschaftlichen Leben Wiens. Im Laufe der Jahrhunderte wurde der Graben mehrfach umgestaltet und erhielt im 18. und 19. Jahrhundert sein heutiges Erscheinungsbild"}, {"kategorie": "", "text": "Eines der bekanntesten Wahrzeichen am Graben ist die [[Pestsäule]], ein barockes Denkmal, das 1693 errichtet wurde, um das Ende der großen Pestepidemie von 1679 zu feiern. Die reich verzierte Säule ist ein wichtiges Beispiel für die barocke Kunst und ein Symbol für Dankbarkeit und Glauben."}]'::jsonb, ''),
  ('pestsaeun', 'Pestsäun', '', '', '', '', 'Pestsäule', '[{"kategorie": "allg.", "text": "\"barockes Denkmal im Herzen Wiens, das sich auf dem [[Graben]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) befindet (auch als \"Dreifaltigkeitssäule\" bekannt)"}, {"kategorie": "", "text": "Sie wurde errichtet, um an das Ende der großen [[Pestepidemie]] von 1679 zu erinnern, die Wien schwer getroffen hatte. Die Pestsäule ist eines der bedeutendsten und bekanntesten Denkmäler der Stadt und ein herausragendes Beispiel für die barocke Kunst"}, {"kategorie": "", "text": "Die Pestsäule wurde von [[Kaiser]] Leopold I. in Auftrag gegeben, der während der Pestepidemie ein Gelübde ablegte, eine Säule zu errichten, wenn die Stadt von der Pest befreit würde. Der Bau der Säule begann 1679 und wurde 1693 vollendet"}, {"kategorie": "", "text": "Der ursprüngliche Entwurf stammte von dem Bildhauer Johann Frühwirth, doch die endgültige Gestaltung wurde maßgeblich von den Künstlern Matthias Rauchmiller und Paul Strudel sowie dem Architekten Johann Bernhard Fischer von Erlach beeinflusst. Fischer von Erlach, einer der bedeutendsten Barockarchitekten, war für das Gesamtkonzept der Säule verantwortlich"}, {"kategorie": "", "text": "Die Säule trägt die Dreifaltigkeit als zentrales Thema, dargestellt durch eine vergoldete Skulpturengruppe an der Spitze, die Gottvater, Jesus Christus und den Heiligen Geist als Taube zeigt. Diese Skulptur wird von einer Wolkensäule getragen, die von Engeln und Heiligen umgeben ist"}, {"kategorie": "", "text": "Auf der Säule ist auch eine Skulptur von Kaiser Leopold I. zu sehen, der kniend Gott um Hilfe anfleht. Diese Darstellung soll an die Frömmigkeit des Kaisers und seine Rolle als Beschützer des Reiches erinnern"}, {"kategorie": "", "text": "Die Säule ist reich an religiöser Symbolik. Sie zeigt neben der Dreifaltigkeit auch verschiedene Heilige, die als Fürsprecher gegen die Pest angerufen wurden, darunter der Heilige Rochus, der Heilige Sebastian und der Heilige Karl Borromäus."}]'::jsonb, ''),
  ('bellariaschdrossn', 'Bellariaschdrossn', '', '', '', '', 'Bellariastraße', '[{"kategorie": "allg.", "text": "kurze, aber bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft parallel zur [[Ringstraße]] und verbindet die [[Burggasse]] mit dem [[Volksgarten]]"}, {"kategorie": "", "text": "Die Bellariastraße wurde 1905 nach der nahegelegenen \"Bellaria\", einem Gebäude, das ursprünglich als kaiserliches Wohnhaus diente, benannt. Der Name \"Bellaria\" leitet sich vom italienischen Begriff für \"schöne Luft\" ab, was auf die attraktive Lage und den Blick auf den Volksgarten hindeutet"}, {"kategorie": "", "text": "Die Gegend um die Bellariastraße war schon im 19. Jahrhundert ein beliebter Standort für die Wiener Aristokratie, die dort prächtige Residenzen und Stadtpalais errichtete. Im Zuge des Ausbaus der Wiener Ringstraße und der Errichtung bedeutender Gebäude in der Umgebung gewann die Bellariastraße weiter an Bedeutung"}]'::jsonb, ''),
  ('buaggossn', 'Buaggossn', '', '', '', '', 'Burggasse', '[{"kategorie": "allg.", "text": "\"wichtige Straße in Wien, die sich über zwei Bezirke erstreckt: den 7. Bezirk ([[Neubau]]) und den 8. Bezirk ([[Josefstadt]])\""}, {"kategorie": "", "text": "Sie beginnt nahe dem [[Museumsquartier]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und führt in westlicher Richtung bis zum [[Gürtel]], wo sie in die [[Thaliastraße]] übergeht"}, {"kategorie": "", "text": "Die Burggasse erhielt ihren Namen aufgrund ihrer Nähe zur Wiener Hofburg, die sie ursprünglich mit den westlichen Vorstädten verband. Der Name \"Burg\" bezieht sich auf diese Verbindung zur ehemaligen kaiserlichen Residenz"}, {"kategorie": "", "text": "Die Burggasse zeichnet sich durch eine abwechslungsreiche Architektur aus, die von historischen Gebäuden aus dem 18. und 19. Jahrhundert bis hin zu modernen Bauten reicht. Entlang der Straße finden sich zahlreiche Geschäfte, Restaurants, Cafés und Kultureinrichtungen"}]'::jsonb, ''),
  ('piaristnplotz', 'Piaristnplotz', '', '', '', '', 'Piaristenplatz', '[{"kategorie": "allg.", "text": "kleiner, aber historisch bedeutsamer Platz im 8. Wiener Gemeindebezirk ([[Josefstadt]])"}, {"kategorie": "", "text": "Er befindet sich direkt vor der [[Piaristenkirche]] Maria Treu und bildet das Zentrum eines malerischen und ruhigen Viertels, das von einer Mischung aus barocker Architektur und charmanten Wohnhäusern geprägt ist"}, {"kategorie": "", "text": "Der Piaristenplatz ist nach dem Piaristenorden benannt, der sich in Wien seit dem späten 17. Jahrhundert niedergelassen hat. Der Orden, der sich der Erziehung und Bildung widmet, spielt eine zentrale Rolle in der Geschichte des Platzes und seiner Umgebung"}, {"kategorie": "", "text": "Der Platz entstand im Zuge der Errichtung der Piaristenkirche Maria Treu und des angrenzenden Piaristengymnasiums. Er entwickelte sich zu einem wichtigen religiösen und schulischen Zentrum im Bezirk Josefstadt"}, {"kategorie": "", "text": "Der Piaristenplatz wird dominiert von der barocken Piaristenkirche Maria Treu, die das architektonische und spirituelle Zentrum des Platzes bildet. Die Kirche mit ihrer prächtigen Fassade und den beiden Türmen ist ein markantes Wahrzeichen und prägt das Erscheinungsbild des Platzes"}, {"kategorie": "", "text": "Rund um den Piaristenplatz stehen mehrere historische Gebäude, darunter das Piaristengymnasium, eine der ältesten Schulen Wiens, sowie weitere barocke und klassizistische Wohnhäuser. Diese Gebäude verleihen dem Platz seinen typischen Wiener Charme und ein Gefühl von Geschichte und Tradition"}]'::jsonb, ''),
  ('leachnfoedaschdrossn', 'Leachnfödaschdrossn', '', '', '', '', 'Lerchenfelder Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße in Wien, die die Bezirke [[Josefstadt]] (8. Bezirk) und [[Neubau]] (7. Bezirk) miteinander verbindet\""}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Gürtel]] (der äußeren Umgehungsstraße Wiens) bis zum [[Museumsquartier]], wo sie in die [[Auerspergstraße]] übergeht"}, {"kategorie": "", "text": "Die Straße ist nach dem ehemaligen Vorort Lerchenfeld benannt, der im 17. Jahrhundert als ein ländliches Gebiet am Rande der Stadt bekannt war. Der Name „Lerchenfeld“ bezieht sich auf die Felder, auf denen früher Lerchen gesungen haben sollen"}, {"kategorie": "", "text": "Die Lerchenfelder Straße ist von einer Mischung aus historischer und moderner Bebauung geprägt. Viele der Gebäude stammen aus dem 19. Jahrhundert und zeigen typische Merkmale des Wiener [[Historismus]] und des Jugendstils. Die Erdgeschosse der meisten Gebäude sind von Geschäften, Cafés und Restaurants besetzt, die der Straße ein lebendiges, urbanes Flair verleihen."}]'::jsonb, ''),
  ('auaspeagschdrossn', 'Auaspeagschdrossn', '', '', '', '', 'Auerspergstraße', '[{"kategorie": "allg.", "text": "bedeutende Straße im 8. Wiener Gemeindebezirk ([[Josefstadt]])"}, {"kategorie": "", "text": "Sie verläuft vom [[Schmerlingplatz]] und dem [[Volksgarten]] im Süden bis zur [[Lerchenfelder]] Straße im Norden"}, {"kategorie": "", "text": "Die Auerspergstraße ist nach der fürstlichen Familie Auersperg benannt, die im 18. Jahrhundert in Wien bedeutenden politischen und gesellschaftlichen Einfluss hatte. Das [[Palais]] Auersperg, das sich in der Nähe der Straße befindet, war ein wichtiger Treffpunkt des Wiener Adels und ist bis heute ein bemerkenswertes Beispiel barocker Architektur"}]'::jsonb, ''),
  ('neubaugossn', 'Neubaugossn', '', '', '', '', 'Neubaugasse', '[{"kategorie": "allg.", "text": "zentrale Einkaufsstraße im 7. Wiener Gemeindebezirk ([[Neubau]])"}, {"kategorie": "", "text": "Sie erstreckt sich von der [[Mariahilfer]] Straße, einer der bekanntesten Einkaufsstraßen Wiens, bis zur [[Lerchenfelder]] Straße und ist ein lebendiger Teil des Viertels, das für seine kreative und alternative Szene bekannt ist"}, {"kategorie": "", "text": "Die Neubaugasse ist nach dem Bezirk Neubau (à7. Wiener Gemeindebezirk) benannt, der im 18. Jahrhundert als eigenständiger Vorort Wiens entstand und später in die Stadt eingegliedert wurde"}, {"kategorie": "", "text": "Die Neubaugasse ist von historischen Gebäuden gesäumt, die meist im Stil des Wiener [[Historismus]] und des Jugendstils erbaut wurden. Die Bauten entlang der Straße sind überwiegend Wohnhäuser mit Geschäften und Lokalen im Erdgeschoss, die den urbanen Charakter der Straße prägen"}, {"kategorie": "", "text": "Die Neubaugasse ist auch ein Zentrum für die alternative Kulturszene Wiens. Hier befinden sich mehrere Galerien, kleine Theater und Veranstaltungsräume, die regelmäßig kulturelle Events, Ausstellungen und Performances bieten"}, {"kategorie": "", "text": "Einmal jährlich wird die Neubaugasse zur Fußgängerzone und Schauplatz eines großen Flohmarkts, der Tausende von Besuchern anzieht. Dieser Flohmarkt ist einer der bekanntesten und beliebtesten in Wien und bietet eine Mischung aus Antiquitäten, Kunsthandwerk und modernen Produkten."}]'::jsonb, ''),
  ('kaisaschdrossn', 'Kaisaschdrossn', '', '', '', '', 'Kaiserstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Geschäftsstraße in Wien, die sich durch den 7. Wiener Gemeindebezirk ([[Neubau]]) und den 8. Bezirk ([[Josefstadt]]) erstreckt. Sie verläuft parallel zur [[Gürtelstraße]] und verbindet die inneren Stadtbezirke mit den westlichen Vororten"}, {"kategorie": "", "text": "Die Kaiserstraße wurde im 18. Jahrhundert nach Kaiser Franz I. Stephan von Lothringen, dem Ehemann von Maria Theresia, benannt. Der Name \"Kaiserstraße\" spiegelt die historische Bedeutung der Straße als eine der Hauptrouten in die Stadt wider"}, {"kategorie": "", "text": "Die Kaiserstraße ist von einer Mischung aus historischen Wohnhäusern und modernen Gebäuden geprägt. Viele der Gebäude stammen aus dem späten 19. und frühen 20. Jahrhundert und sind typische Beispiele für den Wiener [[Historismus]] und den Jugendstil"}, {"kategorie": "", "text": "Die Straße ist eine der längeren Straßen in diesem Teil Wiens und wird von zahlreichen Geschäften, Cafés, Restaurants und kleinen Handwerksbetrieben gesäumt. Das Straßenbild ist lebendig und vielfältig, was der Kaiserstraße ihren urbanen Charakter verleiht."}]'::jsonb, ''),
  ('hofbuag', 'Hofbuag', '', '', '', '', 'Hofburg', '[{"kategorie": "allg", "text": "weitläufiger Palastkomplex im Herzen Wiens, der den Habsburgern über Jahrhunderte hinweg als Hauptresidenz und das Zentrum der politischen Macht im Heiligen Römischen Reich und später in der österreichisch-ungarischen Monarchie diente. Hier residierten Kaiser und Könige, und von hier aus wurde das riesige Reich regiert"}, {"kategorie": "", "text": "Heute ist die Hofburg Sitz des österreichischen Bundespräsidenten und beherbergt zahlreiche Museen und kulturelle Einrichtungen. Sie ist eines der bedeutendsten historischen Gebäude Wiens und ein Symbol der österreichischen Geschichte und Macht"}, {"kategorie": "", "text": "Die Ursprünge der Hofburg reichen bis ins 13. Jahrhundert zurück, als sie als mittelalterliche Burg erbaut wurde. Im Laufe der Jahrhunderte wurde sie kontinuierlich erweitert und umgebaut, um den wachsenden Anforderungen des Habsburgerreichs gerecht zu werden. Die Hofburg spiegelt in ihrer Architektur die verschiedenen Epochen wider, von der Gotik über die Renaissance und den Barock bis hin zum [[Klassizismus]]"}, {"kategorie": "", "text": "Die Hofburg besteht aus zahlreichen Flügeln, Höfen und Plätzen, die im Laufe der Jahrhunderte hinzugefügt wurden. Zu den wichtigsten Teilen der Hofburg gehören: (A) Schweizerhof (der älteste Teil der Hofburg, der auf das 13. Jahrhundert zurückgeht. Er umfasst die Burgkapelle und den Schweizertrakt); (B) Amalienburg (ein Renaissance-Bau, benannt nach der Witwe Kaiser [[Matthias]]’, [[Kaiserin]] Amalie. Er war die Residenz von Kaiserinnen und Kaisern);  (C) Leopoldinischer Trakt (dieser barocke Flügel wurde im 17. Jahrhundert erbaut und dient heute als Amtssitz des österreichischen Bundespräsidenten);  (D) Reichskanzleitrakt (ein weiterer barocker Teil der Hofburg, der im 18. Jahrhundert unter [[Kaiser]] Karl VI. hinzugefügt wurde);  (E) Winterreitschule: Die [[Spanische]] Hofreitschule, die für ihre Vorführungen der Lipizzaner-Pferde bekannt ist, ist ebenfalls Teil der Hofburg;  (F) Neue Burg (der jüngste Teil der Hofburg, der Anfang des 20. Jahrhunderts fertiggestellt wurde. Hier befinden sich heute verschiedene Museen, darunter das [[Weltmuseum]] Wien und das [[Haus]] der Geschichte Österreich)"}]'::jsonb, ''),
  ('hoednplotz', 'Hödnplotz', '', '', '', '', 'Heldenplatz', '[{"kategorie": "historisch", "text": "\"bedeutendster historischer Platz Wiens im Herzen der Stadt\" (diente einst als Parade- und Exerzierplatz, ist umgeben von prächtigen Gebäuden wie der [[Hofburg]] und der [[Nationalbibliothek]] und war Schauplatz vieler wichtiger Ereignisse der österreichischen Geschichte, darunter auch der berühmten Ansprache von Adolf Hitler im Jahr 1938)"}, {"kategorie": "hist., volkstümlich", "text": "\"Promenadenplatz\", \"Paradeplatz\", \"Exerzierplatz\", \"Äußerer Burgplatz\" (Der Heldenplatz in Wien erhielt seinen Namen aufgrund der Denkmäler zweier bedeutender militärischer Helden der österreichischen Geschichte, die dort errichtet wurden. Diese beiden Denkmäler sind Reiterstatuen von [[Erzherzog]] Karl und [[Prinz]] Eugen von Savoyen, die an die militärischen Erfolge und den Ruhm dieser beiden Persönlichkeiten erinnern)"}, {"kategorie": "", "text": "Der Heldenplatz ist geschichtsträchtig und wird oft mit dem 15. März 1938 in Verbindung gebracht, als Adolf Hitler dort vor Hunderttausenden von Menschen den „Anschluss“ Österreichs an das nationalsozialistische Deutschland verkündete. Dieses Ereignis hat den Platz tief in das kollektive Gedächtnis der Österreicher eingebrannt und ihm eine historische Bedeutung verliehen, die bis heute nachwirkt."}]'::jsonb, ''),
  ('schdoodsopa', 'Schdoodsopa', '', '', '', '', 'Staatsoper', '[{"kategorie": "allg., kurz für", "text": "\"Wiener Staatsoper\" - eines der renommiertesten Opernhäuser der Welt und ein zentraler Bestandteil des kulturellen Lebens in Wien und Österreich\""}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk, an der Ringstraße ([[Opernring]]) und ist bekannt für ihre lange Tradition, erstklassige Aufführungen und das jährlich stattfindende [[Opernball-Event]]"}, {"kategorie": "", "text": "Die Wiener Staatsoper wurde am 25. Mai 1869 mit einer Aufführung von Mozarts \"Don Giovanni\" eröffnet. Ursprünglich als \"k.k. Hofoperntheater\" bekannt, wurde das Gebäude im Zuge der Errichtung der [[Ringstraße]] erbaut, die anstelle der alten Stadtmauern entstand"}, {"kategorie": "", "text": "Das Gebäude wurde von den Architekten August Sicard von Siccardsburg und Eduard van der Nüll im Stil der Neorenaissance entworfen"}, {"kategorie": "", "text": "Die Wiener Staatsoper ist ein prächtiges Beispiel für die Architektur der Neorenaissance. Die Fassade ist mit zahlreichen Statuen und Reliefs geschmückt, darunter allegorische Darstellungen der Musik, die das Gebäude schmücken"}, {"kategorie": "", "text": "Das Innere der Staatsoper ist ebenso beeindruckend, mit einem prächtigen Zuschauerraum, der Platz für etwa 1.700 Gäste bietet, und einem Orchestergraben, der für rund 100 Musiker ausgelegt ist. Die Innenräume sind luxuriös mit Marmor, Stuck und Fresken verziert"}, {"kategorie": "", "text": "Das Haus verfügt über ein festes Ensemble von Solisten, einem Chor und dem berühmten Orchester, das gleichzeitig als [[Wiener]] Philharmoniker auftritt"}, {"kategorie": "", "text": "Der [[Wiener]] Opernball, der jedes Jahr in der Staatsoper stattfindet, ist eines der gesellschaftlichen Highlights in Österreich und zieht prominente Gäste aus aller Welt an."}]'::jsonb, ''),
  ('schotzkaumma', 'Schotzkaumma', '', '', '', '', 'Schatzkammer', '[{"kategorie": "kurz für", "text": "\"Kaiserliche Schatzkammer\" = \"Schatzhaus von unschätzbarem Wert, das die prächtigen Schätze der Habsburgerdynastie beherbergt\""}, {"kategorie": "", "text": "Die Schatzkammer befindet sich in der [[Hofburg]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Die Sammlung der Kaiserlichen Schatzkammer geht auf das Mittelalter zurück, als die Habsburger als Kaiser des [[Heiligen]] Römischen Reiches und später als Kaiser von Österreich wichtige dynastische und religiöse Objekte ansammelten"}, {"kategorie": "", "text": "Die Schatzkammer wurde im 19. Jahrhundert für die Öffentlichkeit zugänglich gemacht, ist heute Teil des [[Kunsthistorischen]] Museums Wien und in zwei Bereiche unterteilt: die weltliche Schatzkammer und die geistliche Schatzkammer"}, {"kategorie": "", "text": "In der weltlichen Schatzkammer werden vor allem Objekte von politischer, symbolischer und dynastischer Bedeutung aufbewahrt, darunter: (i) die Kaiserkrone des Heiligen Römischen Reiches (diese Krone aus dem 10. Jahrhundert war das wichtigste Insignium der Kaiser des Heiligen Römischen Reiches und symbolisierte ihre Herrschaft);  (ii) die Österreichische Kaiserkrone (diese Krone wurde 1602 für [[Rudolf]] II. gefertigt und ist das Symbol des [[Kaisertums]] Österreich);  (iii) Reichsinsignien (dazu gehören die Reichskrone, der Reichsapfel, das Reichszepter und andere wichtige Symbole der kaiserlichen Macht); (iv) der Burgundische Schatz (ein umfangreicher Schatz von Schmuckstücken und Kleidungsstücken aus dem Besitz des Herzogtums Burgund, das durch Heirat an die Habsburger fiel);  sowie (v) Schmuck und Prunkwaffen (die Schatzkammer beherbergt auch kostbare Juwelen, Waffen und Rüstungen, die symbolisch für die Herrschaft der Habsburger stehen)"}, {"kategorie": "", "text": "Die geistliche Schatzkammer enthält Objekte, die vor allem religiösen Zwecken dienten und einen hohen sakralen Wert haben, darunter (i) Heilige Reliquien (diese umfassen Reliquien wichtiger Heiliger und Märtyrer, die als Schutz und Symbol der kaiserlichen Macht galten);  (ii) die Krone des Königreichs Lombardei (die sogenannte \"Eiserne Krone\", die mit einer der Nägeln des Kreuzes Christi versehen sein soll);  sowie (iii) geistliche Kunstwerke (kostbare Monstranzen, Kreuze, Altargeräte und andere kirchliche Objekte, die bei Gottesdiensten oder Prozessionen verwendet wurden)"}, {"kategorie": "", "text": "Die Schatzkammer ist eine der bedeutendsten Sammlungen von Kronjuwelen, Insignien und religiösen Artefakten in Europa und ein herausragendes Zeugnis der Geschichte des [[Heiligen]] Römischen Reiches und des Kaisertums Österreich."}]'::jsonb, ''),
  ('albertina', 'Albertina', '', '', '', '', 'Albertina', '[{"kategorie": "allg., kurz für", "text": "\"Wiener Albertina\" - \"eines der bedeutendsten Kunstmuseen in Wien und weltweit bekannt für ihre umfangreiche Sammlung an Grafiken, Zeichnungen und Druckgrafiken\""}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk, in der Nähe der [[Wiener]] Staatsoper und der [[Hofburg]]. Das Museum ist in einem prachtvollen historischen Gebäude untergebracht, das einst als Residenz für Mitglieder der Habsburger-Dynastie diente"}, {"kategorie": "", "text": "Die Albertina wurde 1776 von Herzog Albert von Sachsen-Teschen, einem Schwiegersohn von Kaiserin Maria Theresia, gegründet. Sie entstand aus der persönlichen Sammlung des Herzogs, die er im Laufe seines Lebens durch den Erwerb bedeutender Kunstwerke stetig erweiterte"}, {"kategorie": "", "text": "Das Museum ist nach Herzog Albert benannt. Die Sammlung wuchs unter seiner Leitung und später unter seinen Nachfolgern, zu einer der größten und bedeutendsten grafischen Sammlungen der Welt heran"}, {"kategorie": "", "text": "Die Albertina befindet sich im [[Palais]] Erzherzog Albrecht, einem barocken Stadtpalais, das im Laufe der Jahrhunderte mehrmals umgebaut wurde und heute eine prächtige Mischung aus barocker und [[klassizistischer]] Architektur darstellt"}, {"kategorie": "", "text": "Die Albertina beherbergt eine der weltweit bedeutendsten Sammlungen von Zeichnungen, Aquarellen und Druckgrafiken. Zu den Highlights der Sammlung gehören Werke von Albrecht Dürer, Michelangelo, Raphael, Rembrandt, Pieter Bruegel dem Älteren, Rubens und vielen anderen Meistern der europäischen Kunstgeschichte"}, {"kategorie": "", "text": "Dürers \"Feldhase\" und \"Betende Hände\" zählen zu den berühmtesten Exponaten der Albertina"}, {"kategorie": "", "text": "Neben der historischen grafischen Sammlung besitzt die Albertina auch bedeutende Bestände moderner und zeitgenössischer Kunst, darunter Werke von Pablo Picasso, Egon Schiele, Gustav Klimt, Wassily Kandinsky und weiteren Künstlern des 19. und 20. Jahrhunderts"}, {"kategorie": "", "text": "Die Albertina verfügt über prunkvolle Innenräume, die teilweise im Stil des Klassizismus und Empire gestaltet sind. Diese Räume geben einen Einblick in die Pracht der ehemaligen Habsburger Residenz und sind selbst ein bedeutendes kulturelles Erbe"}, {"kategorie": "", "text": "Ein markantes architektonisches Merkmal der Albertina ist der sogenannte \"Flügel des Erzherzogs\", eine monumentale Freitreppe mit einer modernen Überdachung, die das historische Gebäude mit zeitgenössischer Architektur verbindet."}]'::jsonb, ''),
  ('khm', 'KHM', '', '', '', '', 'KHM', '[{"kategorie": "", "text": "(wörtlich, Abkürzung für \"Kunsthistorisches Museum Wien\" =  \"eines der bedeutendsten und größten Kunstmuseen der Welt\""}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), an der [[Ringstraße]], gegenüber dem [[Naturhistorischen]] Museum, mit dem es eine symmetrische architektonische Einheit bildet"}, {"kategorie": "", "text": "Das Kunsthistorische Museum wurde von den Architekten Gottfried Semper und Carl von Hasenauer entworfen. Es wurde errichtet, um die kaiserlichen Kunstsammlungen der Öffentlichkeit zugänglich zu machen und ist ein prächtiges Beispiel für den [[Historismus]] des 19. Jahrhunderts"}, {"kategorie": "", "text": "Das Museum wurde 1891 unter Kaiser Franz Joseph I. eröffnet, zusammen mit dem gegenüberliegenden Naturhistorischen Museum. Beide Gebäude sind Teil des großen Ringstraßenprojekts, das nach dem Abriss der Stadtmauern im 19. Jahrhundert realisiert wurde"}, {"kategorie": "", "text": "Das Gebäude ist im Stil der italienischen Renaissance erbaut und zeichnet sich durch seine imposante Kuppel und die reich verzierten Fassaden aus. Die Innenräume sind ebenso prächtig gestaltet, mit Marmortreppen, großen Korridoren, Kuppelräumen und opulenten Deckenfresken, die von Künstlern wie Gustav Klimt, Ernst Klimt und Franz Matsch geschaffen wurden. Die prächtige Eingangshalle und die Haupttreppe sind architektonische Highlights und bieten den Besuchern einen ersten Eindruck von der künstlerischen Pracht des Museums"}, {"kategorie": "", "text": "Die Gemäldegalerie des Kunsthistorischen Museums zählt zu den bedeutendsten der Welt. Sie enthält Meisterwerke von Künstlern wie Pieter Bruegel dem Älteren, Albrecht Dürer, Raffael, Caravaggio, Peter Paul Rubens, Rembrandt und Diego Velázquez. Besonders hervorzuheben ist die Sammlung von Gemälden Pieter Bruegels, die die größte ihrer Art weltweit ist"}, {"kategorie": "", "text": "Die Kunstkammer Wien ist eine der bedeutendsten Sammlungen ihrer Art und umfasst kunsthandwerkliche Meisterwerke, Kuriositäten und wissenschaftliche Instrumente aus der Renaissance und dem Barock. Sie enthält berühmte Stücke wie die Saliera von Benvenuto Cellini"}, {"kategorie": "", "text": "Das Münzkabinett des Museums ist eine der größten und ältesten Sammlungen von Münzen, Medaillen und Geldscheinen der Welt"}, {"kategorie": "", "text": "Weitere bedeutende Sammlungen sind die Ägyptisch-Orientalische Sammlung (umfasst eine der bedeutendsten Sammlungen altägyptischer Kunst und Kultur in Europa, darunter die berühmte Totenmaske der Königin Teje und zahlreiche Sarkophage, Statuen und Reliefs) sowie die Antikensammlung (umfasst griechische, römische und etruskische Kunstwerke, darunter Skulpturen, Vasen und Mosaiken)"}]'::jsonb, 'Kunsthistorisches Museum'),
  ('museumsquatia', 'Museumsquatia', '', '', '', '', 'Museumsquartier', '[{"kategorie": "allg.", "text": "\"eines der größten Kulturkomplexe der Welt und ein zentraler Ort für Kunst, Kultur und Freizeit in der Stadt\", kurz auch als \"MQ\" bezeichnet"}, {"kategorie": "", "text": "Es befindet sich im 7. Wiener Gemeindebezirk ([[Neubau]]), direkt an der Grenze zur [[Inneren]] Stadt, in unmittelbarer Nähe zur [[Mariahilfer]] Straße und dem [[Volkstheater]]"}, {"kategorie": "hist.", "text": "Das MuseumsQuartier wurde auf dem Gelände der ehemaligen Hofstallungen erbaut, die im 18. Jahrhundert von [[Kaiser]] Karl VI. in Auftrag gegeben wurden. Die ursprünglichen Gebäude, die von dem Architekten Johann Bernhard Fischer von Erlach entworfen wurden, dienten als kaiserliche Reit- und Wagenburg. Im Laufe des 20. Jahrhunderts verlor der Standort seine ursprüngliche Funktion und wurde für verschiedene Zwecke genutzt, bevor schließlich die Idee entstand, das Areal in einen Kulturkomplex umzuwandeln"}, {"kategorie": "", "text": "Nach umfangreichen Umbau- und Erweiterungsarbeiten wurde das MuseumsQuartier im Jahr 2001 offiziell eröffnet. Der historische Bestand wurde dabei durch moderne Architekturelemente ergänzt, um ein harmonisches Zusammenspiel zwischen Alt und Neu zu schaffen"}, {"kategorie": "", "text": "Die alten barocken Stallungen wurden restauriert und mit modernen Gebäuden erweitert, darunter das auffällig dunkle [[MUMOK]] (Museum Moderner Kunst Stiftung Ludwig Wien) und das helle [[Leopold Museum]]"}, {"kategorie": "", "text": "Das MQ ist bekannt für seine großzügigen Innenhöfe und Freiflächen, die als Treffpunkt und Veranstaltungsort dienen. Diese öffentlichen Räume sind ein integraler Bestandteil des Quartiers und werden oft für Veranstaltungen, Installationen und als Aufenthaltsbereich genutzt."}]'::jsonb, ''),
  ('mq', 'MQ', '', '', '', '', 'MQ', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Museumsquartier\" =  \"eines der größten Kulturkomplexe der Welt und ein zentraler Ort für Kunst, Kultur und Freizeit in der Stadt\", kurz auch als \"MQ\" bezeichnet"}, {"kategorie": "", "text": "Es befindet sich im 7. Wiener Gemeindebezirk ([[Neubau]]), direkt an der Grenze zur [[Inneren]] Stadt, in unmittelbarer Nähe zur [[Mariahilfer]] Straße und dem [[Volkstheater]]"}, {"kategorie": "hist.", "text": "Das MuseumsQuartier wurde auf dem Gelände der ehemaligen Hofstallungen erbaut, die im 18. Jahrhundert von Kaiser Karl VI. in Auftrag gegeben wurden. Die ursprünglichen Gebäude, die von dem Architekten Johann Bernhard Fischer von Erlach entworfen wurden, dienten als kaiserliche Reit- und Wagenburg. Im Laufe des 20. Jahrhunderts verlor der Standort seine ursprüngliche Funktion und wurde für verschiedene Zwecke genutzt, bevor schließlich die Idee entstand, das Areal in einen Kulturkomplex umzuwandeln"}, {"kategorie": "", "text": "Nach umfangreichen Umbau- und Erweiterungsarbeiten wurde das MuseumsQuartier im Jahr 2001 offiziell eröffnet. Der historische Bestand wurde dabei durch moderne Architekturelemente ergänzt, um ein harmonisches Zusammenspiel zwischen Alt und Neu zu schaffen"}, {"kategorie": "", "text": "Die alten barocken Stallungen wurden restauriert und mit modernen Gebäuden erweitert, darunter das auffällig dunkle [[MUMOK]] (Museum Moderner Kunst Stiftung Ludwig Wien) und das helle [[Leopold Museum]]"}, {"kategorie": "", "text": "Das MQ ist bekannt für seine großzügigen Innenhöfe und Freiflächen, die als Treffpunkt und Veranstaltungsort dienen. Diese öffentlichen Räume sind ein integraler Bestandteil des Quartiers und werden oft für Veranstaltungen, Installationen und als Aufenthaltsbereich genutzt."}]'::jsonb, ''),
  ('mumok', 'MUMOK', '', '', '', '', 'MUMOK', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Museum Moderner Kunst Stiftung Ludwig Wien\" (größtes Museum für moderne und zeitgenössische Kunst in Österreich)"}, {"kategorie": "", "text": "Es befindet sich im [[Wiener]] Museumsquartier (MQ) im 7. Bezirk ([[Neubau]]) und ist eine zentrale Institution für die Präsentation und Vermittlung moderner Kunst"}, {"kategorie": "", "text": "Das MUMOK wurde 1962 als Museum des 20. Jahrhunderts gegründet. Ursprünglich befand es sich im Wiener [[Schweizergarten]] und wurde 1979 in das [[Palais]] Liechtenstein verlegt. 2001 zog das Museum in das neu errichtete Gebäude im MuseumsQuartier, das seither sein fester Standort ist"}, {"kategorie": "", "text": "1981 erhielt das Museum durch die Schenkung der Sammlung Ludwig, einer der bedeutendsten privaten Kunstsammlungen Europas, einen entscheidenden Zuwachs. Diese Schenkung führte zur Umbenennung in Museum Moderner Kunst Stiftung Ludwig Wien (MUMOK)."}]'::jsonb, ''),
  ('secession', 'Secession', '', '', '', '', 'Secession', '[{"kategorie": "allg., kurz für", "text": "\"Wiener Sezession\" = \"ein bedeutendes Ausstellungshaus und ein Symbol für die Wiener Moderne\""}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), nahe dem [[Naschmarkt]]"}, {"kategorie": "", "text": "Die Wiener Secession wurde 1897 von einer Gruppe von Künstlern gegründet, darunter Gustav Klimt, Koloman Moser, Josef Hoffmann und andere. Diese Künstler wollten sich von den konservativen Kunsttraditionen der damaligen Zeit lösen und gründeten die \"Vereinigung bildender Künstler Österreichs – Secession\". Das Ziel war, moderne Kunstformen zu fördern und ein Forum für die internationale Avantgarde zu schaffen"}, {"kategorie": "", "text": "Gustav Klimt war der erste Präsident der Wiener Secession und spielte eine zentrale Rolle in der Entwicklung der Bewegung. Die Secession wurde zum Zentrum des Wiener Jugendstils, auch bekannt als Art Nouveau, und war maßgeblich an der Entwicklung der Wiener Moderne beteiligt"}, {"kategorie": "", "text": "Das Secessionsgebäude, oft einfach \"Die Secession\" genannt, wurde von dem Architekten Joseph Maria Olbrich entworfen und 1898 eröffnet. Das Gebäude ist ein herausragendes Beispiel für den Jugendstil und gilt als eines der bedeutendsten Bauwerke dieser Epoche"}, {"kategorie": "", "text": "Das auffälligste Merkmal des Gebäudes ist die goldene Kuppel, die aus Hunderten von vergoldeten Lorbeerblättern besteht. Sie wird oft als \"goldenes [[Krauthappel]]\" (goldener Kohlkopf) bezeichnet und ist zu einem ikonischen Symbol der Wiener Secession und der Stadt Wien selbst geworden"}, {"kategorie": "", "text": "Die Fassade des Gebäudes ist mit dem berühmten Motto der Secession geschmückt: „Der Zeit ihre Kunst, der Kunst ihre Freiheit.“ Dieses Zitat spiegelt den revolutionären Geist der Künstlerbewegung wider"}, {"kategorie": "", "text": "Eines der bekanntesten Kunstwerke, das sich im Inneren der Secession befindet, ist der Beethovenfries von Gustav Klimt. Dieses monumentale Wandgemälde wurde 1902 für eine Ausstellung zu Ehren Ludwig van Beethovens geschaffen und gilt als eines der Meisterwerke des Jugendstils."}]'::jsonb, 'Iwa Wean glänzd a goidanes Krauthappä - jo, so haassd bei uns de Wiina Secession, und zwoa weeng iara goidanan Kuppä!'),
  ('ringschdrossn', 'Ringschdrossn', '', '', '', '', 'Ringstraße', '[{"kategorie": "historisch", "text": "\"berühmte Prachtstraße in Wien, die das historische Zentrum der Stadt, die Innere Stadt, umschließt.\""}, {"kategorie": "", "text": "Die Wiener Ringstraße entstand in der zweiten Hälfte des 19. Jahrhunderts, nachdem Kaiser Franz Joseph I. im Jahr 1857 den Abriss der alten Stadtbefestigungen angeordnet hatte. An deren Stelle wurde die Ringstraße als großzügiger Boulevard angelegt, der zwischen 1857 und 1865 geplant und in den folgenden Jahrzehnten fertiggestellt wurde.  3. Viele der Gebäude entlang der Ringstraße wurden von namhaften Architekten im Stil der Neorenaissance, Neugotik und des Neobarocks entworfen, und sie spiegeln die kulturelle Blütezeit der [[Habsburgermonarchie]] wider"}, {"kategorie": "", "text": "Die Wiener Ringstraße setzt sich aus folgenden Teilabschnitten zusammen (im Uhrzeigersinn aufgeführt, beginnend im Nordwesten): [[Schottenring]], [[Universitätsring]], [[Dr]].-Karl-Renner-Ring, [[Burgring]], [[Opernring]], [[Kärntner]] Ring, [[Schubertring]], [[Parkring]] und [[Stubenring]]"}]'::jsonb, ''),
  ('ring', 'Ring', '', '', '', '', 'Ring', '[{"kategorie": "wörtlich, kurz für", "text": "\"Wiener Ringstraße\" (berühmte Prachtstraße in Wien, die das historische Zentrum der Stadt, die Innere Stadt, umschließt)"}, {"kategorie": "", "text": "Die Wiener Ringstraße entstand in der zweiten Hälfte des 19. Jahrhunderts, nachdem Kaiser Franz Joseph I. im Jahr 1857 den Abriss der alten Stadtbefestigungen angeordnet hatte. An deren Stelle wurde die Ringstraße als großzügiger Boulevard angelegt, der zwischen 1857 und 1865 geplant und in den folgenden Jahrzehnten fertiggestellt wurde.  3. Viele der Gebäude entlang der Ringstraße wurden von namhaften Architekten im Stil der Neorenaissance, Neugotik und des Neobarocks entworfen, und sie spiegeln die kulturelle Blütezeit der [[Habsburgermonarchie]] wider"}, {"kategorie": "", "text": "Die Wiener Ringstraße setzt sich aus folgenden Teilabschnitten zusammen (im Uhrzeigersinn aufgeführt, beginnend im Nordwesten): [[Schottenring]], [[Universitätsring]], [[Dr]].-Karl-Renner-Ring, [[Burgring]], [[Opernring]], [[Kärntner]] Ring, [[Schubertring]], [[Parkring]] und [[Stubenring]]"}]'::jsonb, ''),
  ('schubeatring', 'Schubeatring', '', '', '', '', 'Schubertring', '[{"kategorie": "allg.", "text": "Abschnitt der [[Wiener]] Ringstraße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), der nach dem berühmten österreichischen Komponisten Franz Schubert benannt ist"}, {"kategorie": "", "text": "Er liegt zwischen dem [[Kärntner]] Ring und dem [[Parkring]] und beherbergt eine Reihe von architektonisch und historisch bedeutenden Gebäuden"}, {"kategorie": "", "text": "Wie viele Teile der Wiener Ringstraße ist auch der Schubertring durch eine architektonische Vielfalt gekennzeichnet, die verschiedene Stile des [[Historismus]] und des Jugendstils vereint"}, {"kategorie": "", "text": "Der Schubertring ist ein Teil des umfassenderen Konzepts der Ringstraße, das die alte Stadtmauer Wiens ersetzt und die Stadt im 19. Jahrhundert modernisierte und verschönerte. Er trägt durch seinen Namen zur Ehrung von Franz Schubert bei, einem der bedeutendsten Komponisten der Romantik, der eng mit Wien verbunden ist."}]'::jsonb, ''),
  ('parlament', 'Parlament', '', '', '', '', 'Parlament', '[{"kategorie": "pol.", "text": "\"Das österreichische Parlament\" = \"Sitz der beiden Kammern der österreichischen Legislative, dem Nationalrat und dem Bundesrat\""}, {"kategorie": "", "text": "Das Parlamentsgebäude befindet sich in der Wiener Innenstadt, am [[Dr]].-Karl-Renner-Ring, einem Abschnitt der berühmten [[Wiener]] Ringstraße, in unmittelbarer Nähe zur [[Hofburg]] und dem [[Rathaus]]. Es ist eines der markantesten Bauwerke der Stadt und wurde zwischen 1874 und 1883 im Rahmen des großen Ringstraßenprojekts errichtet, das nach dem Abriss der Wiener Stadtmauern initiiert wurde. Der Entwurf stammt von dem dänisch-österreichischen Architekten Theophil Hansen, der das Gebäude im Stil des griechischen [[Klassizismus]] gestaltete, um an die demokratischen Ideale des antiken Griechenlands zu erinnern"}, {"kategorie": "", "text": "Die beeindruckende Hauptfassade des Parlamentsgebäudes wird von einem großen [[Portikus]] mit acht korinthischen Säulen dominiert, die zu einem zentralen Giebel führen. Vor dem Gebäude steht die imposante Pallas-Athene-Brunnenstatue, die Weisheit und Staatskunst symbolisiert"}, {"kategorie": "", "text": "Die Innenräume des Parlaments sind ebenso prachtvoll und umfassen mehrere Sitzungssäle, darunter den Sitzungssaal des Nationalrats und des Bundesrats, sowie reich verzierte Empfangsräume. Besonders bemerkenswert ist die zentrale Säulenhalle, die mit 24 korinthischen Säulen aus Adneter Marmor gestaltet ist und als Hauptzugang zu den Kammern dient"}, {"kategorie": "", "text": "Das Parlamentsgebäude wurde zwischen 2017 und 2022 umfassend renoviert, um es den modernen Anforderungen anzupassen und gleichzeitig die historische Substanz zu bewahren."}]'::jsonb, ''),
  ('voiksopa', 'Voiksopa', '', '', '', '', 'Volksoper', '[{"kategorie": "allg., kurz für", "text": "\"Die Wiener Volksoper\" = \"eines der bekanntesten Opernhäuser in Wien und ein zentraler Ort für Musiktheater in Österreich\""}, {"kategorie": "", "text": "Sie befindet sich im 9. Wiener Gemeindebezirk ([[Alsergrund]]) und ist auf Operetten, Musicals, klassische Opern und Ballettaufführungen spezialisiert. Die Volksoper ergänzt damit die [[Wiener]] Staatsoper und hat sich einen eigenen Platz im kulturellen Leben Wiens erobert"}, {"kategorie": "", "text": "Die Volksoper wurde 1898 als \"Kaiser-Jubiläums-Stadttheater\" eröffnet, um das 50-jährige Regierungsjubiläum von [[Kaiser]] Franz Joseph I. zu feiern. Ursprünglich als Sprechtheater konzipiert, wurden dort in den ersten Jahren vor allem Schauspiele aufgeführt"}, {"kategorie": "", "text": "1903 begann das Theater, Opern und Operetten in sein Programm aufzunehmen, was zu einem bedeutenden Wandel führte. Ab 1908 spezialisierte sich das Haus vollständig auf das Musiktheater und erhielt 1909 den Namen \"Volksoper\""}, {"kategorie": "", "text": "Das Gebäude der Volksoper ist im Stil der Neorenaissance erbaut und wurde in den Jahren seines Bestehens mehrfach umgebaut und renoviert, um den sich ändernden Anforderungen des Theaterbetriebs gerecht zu werden"}, {"kategorie": "", "text": "Der Zuschauerraum bietet Platz für rund 1.300 Besucher und ist für seine gute Akustik und das intime Ambiente bekannt, das sich für die Aufführung von Operetten und Musicals besonders eignet."}]'::jsonb, ''),
  ('buaggoatn', 'Buaggoatn', '', '', '', '', 'Burggarten', '[{"kategorie": "allg.", "text": "\"historischer Park im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), der direkt an die [[Hofburg]], den ehemaligen kaiserlichen Palast, angrenzt\""}, {"kategorie": "", "text": "Der Burggarten war ursprünglich ein privater Garten für Kaiser [[Franz]] I. und seine Nachfolger. Der Park wurde im Stil eines englischen Landschaftsgartens gestaltet, was durch eine natürliche, unregelmäßige Anordnung von Wegen, Rasenflächen und Baumbeständen gekennzeichnet ist"}, {"kategorie": "", "text": "Im Jahr 1919, nach dem Ende der Monarchie, wurde der Burggarten für die Öffentlichkeit zugänglich gemacht und ist seitdem ein beliebter Erholungsort in der Wiener Innenstadt"}, {"kategorie": "", "text": "Eines der bekanntesten Denkmäler im Burggarten ist das Mozart-Denkmal, das ursprünglich am Albrechtsplatz (heute Albertinaplatz) stand und 1953 in den Burggarten verlegt wurde. Es zeigt eine Statue des Komponisten Wolfgang Amadeus Mozart auf einem hohen Sockel, umgeben von Blumenbeeten, die häufig in Form eines Violinschlüssels angeordnet sind"}, {"kategorie": "", "text": "Der Burggarten enthält auch ein Denkmal für Kaiser Franz I. (1768–1835), der den Burggarten als seine private Gartenanlage nutzte"}, {"kategorie": "", "text": "Das Palmenhaus im Burggarten ist eines der größten und schönsten seiner Art in Europa. Es wurde 1901 im Jugendstil erbaut und ist ein beeindruckender Glas-Eisen-Bau. Das Palmenhaus beherbergt eine große Sammlung tropischer Pflanzen sowie ein Café und einen Schmetterlingspavillon (Schmetterlinghaus), der exotische Schmetterlinge ausstellt."}]'::jsonb, ''),
  ('voiksgoatn', 'Voiksgoatn', '', '', '', '', 'Volksgarten', '[{"kategorie": "allg.", "text": "\"5 Hektar große öffentliche Parkanlage an der Ringstraße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Er wurde 1823 eröffnet, ist der erste öffentliche Park Wiens und liegt zwischen der [[Hofburg]], dem [[Burgtheater]] und dem [[Parlamentsgebäude]]"}, {"kategorie": "", "text": "Ursprünglich war das Gebiet Teil der Verteidigungsanlagen vor der Hofburg und gehörte zu den [[Basteien]] der alten [[Stadtmauer]]"}, {"kategorie": "", "text": "Nachdem [[Napoleons]] Truppen 1809 die Stadtmauer beschädigt hatten, wurde das Gelände für die Errichtung des Volksgartens freigegeben"}, {"kategorie": "", "text": "Die Gestaltung des Parks erfolgte im Stil eines französischen Barockgartens, der durch symmetrische Beete und geometrische Anordnung gekennzeichnet ist"}, {"kategorie": "", "text": "Der Volksgarten ist besonders berühmt für seine prächtigen Rosenbeete, seine klassizistische Architektur und seine entspannte Atmosphäre, die ihn zu einem beliebten Erholungsort für Einheimische und Touristen macht"}, {"kategorie": "", "text": "Das architektonische Highlight des Volksgartens ist der [[Theseustempel]], eine Nachbildung des antiken Tempels des Hephaistos in Athen, der von Peter von Nobile zwischen 1819 und 1823 errichtet wurde"}, {"kategorie": "", "text": "Der klassizistische Bau diente ursprünglich als Ausstellungsraum für die Statue \"Theseus besiegt den Kentauren\" von Antonio Canova, die später ins [[Kunsthistorische]] Museum gebracht wurde. Der Tempel steht im Zentrum des Parks und ist ein Symbol für den [[Wiener]] Klassizismus"}, {"kategorie": "", "text": "Im Volksgarten befindet sich auch ein Denkmal für Kaiserin Elisabeth, besser bekannt als [[Sisi]], die ikonische Kaiserin von Österreich. Das Denkmal zeigt eine sitzende Statue der Kaiserin und ist ein beliebter Anziehungspunkt im Park."}]'::jsonb, ''),
  ('tu', 'TU', '', '', '', '', 'TU', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Technische Universität Wien\" (eine der führenden technischen Universitäten in Österreich und eine bedeutende akademische Institution in Europa\""}, {"kategorie": "", "text": "Sie befindet sich im 4. Wiener Gemeindebezirk ([[Wieden]]), in unmittelbarer Nähe zum [[Karlsplatz]], und wurde 1815 als \"k.k. Polytechnisches Institut\" gegründet. Sie ist damit eine der ältesten technischen Hochschulen im deutschsprachigen Raum"}, {"kategorie": "", "text": "Die TU Wien gilt als eine der besten technischen Universitäten in Europa und genießt weltweit hohes Ansehen für ihre Lehre und Forschung. Sie zieht Studierende und Wissenschaftler aus aller Welt an und trägt wesentlich zur akademischen und wissenschaftlichen Landschaft Wiens bei."}]'::jsonb, ''),
  ('mak', 'MAK', '', '', '', '', 'MAK', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Museum für Angewandte Kunst\" (eines der weltweit führenden Museen für angewandte Kunst und Design)"}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) am [[Stubenring]] und ist ein zentraler Ort für die Präsentation und Erforschung von Kunsthandwerk, Design, Architektur und Gegenwartskunst"}, {"kategorie": "", "text": "Das MAK wurde 1863 als Österreichisches Museum für Kunst und Industrie gegründet. Es entstand aus der Idee, handwerkliche und industrielle Qualität zu fördern und Inspiration durch das Sammeln und Ausstellen von Kunstwerken zu bieten. Der Gründer, Rudolf von Eitelberger, war ein Pionier in der Kunst- und Designförderung und setzte mit der Gründung des Museums neue Maßstäbe in der Vermittlung von Kunsthandwerk"}, {"kategorie": "", "text": "Eine der bedeutendsten Sammlungen des MAK umfasst Werke der Wiener Werkstätte, einer Designbewegung des frühen 20. Jahrhunderts, die von Künstlern wie Josef Hoffmann und Koloman Moser geprägt wurde. Diese Sammlung ist besonders für ihre hochwertigen Kunstwerke und ihre Bedeutung in der Geschichte des Designs bekannt"}, {"kategorie": "", "text": "Das MAK-Gebäude am Stubenring ist ein architektonisches Meisterwerk des [[Historismus]]. Es wurde von Heinrich von Ferstel entworfen und vereint Elemente der Neorenaissance mit funktionalen Aspekten, die für ein Museum notwendig sind. Die großzügigen Ausstellungsräume und die beeindruckende Fassade machen das MAK zu einem wichtigen kulturellen Wahrzeichen Wiens."}]'::jsonb, 'Museum fia Aungewaundte Kunst'),
  ('getreidemoakd', 'Getreidemoakd', '', '', '', '', 'Getreidemarkt', '[{"kategorie": "historisch", "text": "Straße an der Grenze zwischem 1. und 6. Bezirk in Wien (benannt 1866 zur Erinnerung an den bis 1864 hier abgehaltenen Markt für Getreide und das bis 1900 in der Nähe befindliche städtische Getreidemagazin (6, Rahlgasse 3; Zum goldenen Metzen), das neben der späteren Getreidemarktkaserne lag)"}, {"kategorie": "heute", "text": "Pulsierende Ader der Stadt (gesäumt von historischen Gebäuden und belebten Straßencafés, die das kulturelle Erbe der Stadt lebendig halten. Direkt neben der Wiener Secession gelegen, strahlt der Getreidemarkt eine künstlerische Atmosphäre aus, in der sich Tradition und Moderne harmonisch vereinen)"}]'::jsonb, ''),
  ('juudnplotz', 'Juudnplotz', '', '', '', '', 'Judenplatz', '[{"kategorie": "allg.", "text": "\"historisch bedeutender Platz im 1. Wiener Gemeindebezirk à(Innere Stadt), der eng mit der jüdischen Geschichte der Stadt verbunden ist\""}, {"kategorie": "", "text": "Er liegt im Herzen der Wiener Altstadt und ist heute sowohl ein Gedenkort als auch ein lebendiges Zentrum, das an die jahrhundertelange jüdische Präsenz in Wien erinnert"}, {"kategorie": "", "text": "Der Judenplatz war im Mittelalter das Zentrum des jüdischen Lebens in Wien. Bereits im 13. Jahrhundert entstand hier eine jüdische Siedlung, die sogenannte Wiener Judenstadt, die zu den größten jüdischen Gemeinden im deutschsprachigen Raum zählte"}, {"kategorie": "", "text": "Diese blühende Gemeinschaft erlitt 1420–1421 während des Wiener Geserah, eines Pogroms, ein tragisches Ende. Die jüdische Bevölkerung wurde vertrieben oder ermordet, und die Synagoge am Judenplatz wurde zerstört. Auf den Ruinen der mittelalterlichen Synagoge wurde später ein neues Stadtviertel errichtet"}, {"kategorie": "", "text": "Im Zuge von Bauarbeiten in den 1990er Jahren wurden die Reste der mittelalterlichen Synagoge am Judenplatz entdeckt. Diese Synagoge war im 14. Jahrhundert errichtet worden und galt als eines der größten jüdischen Gotteshäuser in Europa. Die Überreste der Synagoge sind heute in einem unterirdischen Museum zu besichtigen, das Teil des [[Jüdischen]] Museums Wien ist"}, {"kategorie": "", "text": "Eine zentrale und eindrucksvolle Gedenkstätte am Judenplatz ist das Holocaust-Mahnmal, das an die 65.000 österreichischen Juden, die während des Holocausts von den Nationalsozialisten ermordet wurden, erinnert. Das Mahnmal wurde von der britischen Künstlerin Rachel Whiteread entworfen und im Jahr 2000 enthüllt."}]'::jsonb, ''),
  ('bluatgossn', 'Bluatgossn', '', '', '', '', 'Blutgasse', '[{"kategorie": "hist.", "text": "\"historische Gasse im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie liegt im sogenannten [[Blutgassenviertel]] in der Nähe des [[Stephansdoms]], zählt zu den ältesten Straßen Wiens und ist für ihre malerische und mittelalterliche Atmosphäre bekannt"}, {"kategorie": "Namensherkunft", "text": "Eine der bekanntesten Legenden besagt, dass der Name von einem blutigen Massaker an den Tempelrittern herrührt, das im 14. Jahrhundert in der Gasse stattgefunden haben soll. Eine andere Theorie besagt, dass der Name von den Metzgern herrührt, die in dieser Gegend ansässig waren und dort ihr Handwerk ausübten"}, {"kategorie": "", "text": "Die Blutgasse und das umliegende Viertel gehören zu den ältesten Teilen Wiens und haben ihren mittelalterlichen Charakter weitgehend bewahrt. Die enge, kopfsteingepflasterte Gasse und die gut erhaltenen historischen Gebäude vermitteln einen Eindruck von Wien im Mittelalter"}]'::jsonb, ''),
  ('bluatgossnviatl', 'Bluatgossnviatl', '', '', '', '', 'Blutgassenviertel', '[{"kategorie": "hist.", "text": "\"historisches Viertel im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt), nahe dem [[Stephansdom]]"}, {"kategorie": "", "text": "Es umfasst einige der ältesten und malerischsten Gassen Wiens, darunter die berühmte [[Blutgasse]], und ist bekannt für seine mittelalterliche Atmosphäre und seine gut erhaltene historische Architektur"}, {"kategorie": "", "text": "Das Blutgassenviertel ist geprägt von engen, kopfsteingepflasterten Gassen, die einen Großteil ihres mittelalterlichen Charakters bewahrt haben. Zu den wichtigsten Straßen und Gassen des Viertels gehören neben der Blutgasse auch die [[Domgasse]], die [[Grünangergasse]] und die [[Schönlaterngasse]]."}]'::jsonb, ''),
  ('gruenaungagossn', 'Grünaungagossn', '', '', '', '', 'Grünangergasse', '[{"kategorie": "hist.", "text": "historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie liegt im sogenannten [[Blutgassenviertel]], einem der ältesten und geschichtsträchtigsten Teile Wiens, in der Nähe des [[Stephansdoms]]"}, {"kategorie": "", "text": "Die Gasse ist bekannt für ihre gut erhaltene historische Architektur und ihre enge, verwinkelte Struktur, die an das mittelalterliche Wien erinnert"}, {"kategorie": "", "text": "Die Grünangergasse ist von zahlreichen gut erhaltenen historischen Gebäuden gesäumt, die typisch für die Wiener Altstadt sind. Viele dieser Häuser stammen aus dem 17. und 18. Jahrhundert und zeigen architektonische Merkmale der Barock- und Biedermeierzeit, wie verzierte Fassaden, Erker und schmiedeeiserne Details"}]'::jsonb, ''),
  ('scheenlateangossn', 'Scheenlateangossn', '', '', '', '', 'Schönlaterngasse', '[{"kategorie": "hist.", "text": "historische und malerische Gasse im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie liegt im sogenannten [[Blutgassenviertel]], einem der ältesten Teile Wiens, und ist bekannt für ihre gut erhaltene mittelalterliche Architektur sowie ihre enge, verwinkelte Struktur"}, {"kategorie": "", "text": "Eines der bekanntesten Gebäude in der Schönlaterngasse ist das sogenannte Basiliskenhaus (Schönlaterngasse 7), das mit einer berühmten Wiener Sage verbunden ist. Der Legende nach soll hier im 13. Jahrhundert ein Basilisk, ein mythisches Fabelwesen, entdeckt worden sein. Das Haus ist heute mit einer Reliefdarstellung des Basilisken geschmückt und eine beliebte Sehenswürdigkeit"}]'::jsonb, ''),
  ('domgossn', 'Domgossn', '', '', '', '', 'Domgasse', '[{"kategorie": "hist.", "text": "\"historische Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie liegt im sogenannten [[Blutgassenviertel]], d.h. im unmittelbaren Umfeld des [[Stephansdoms]], und gehört zu den ältesten Gassen der Stadt Wien"}, {"kategorie": "", "text": "Eine der wichtigsten Sehenswürdigkeiten in der Domgasse ist das [[Mozarthaus]] Wien (Domgasse 5), in dem Wolfgang Amadeus Mozart von 1784 bis 1787 lebte. Hier komponierte er einige seiner berühmtesten Werke, darunter \"Die Hochzeit des Figaro\". Das Gebäude ist heute ein Museum, das dem Leben und Werk Mozarts gewidmet ist und ein beliebtes Ziel für Touristen aus aller Welt."}]'::jsonb, ''),
  ('muk', 'MUK', '', '', '', '', 'MUK', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Musik und Kunst Privatuniversität der Stadt Wien\" (früher [[Konservatorium Wien]])"}, {"kategorie": "", "text": "renommierte Bildungseinrichtung für Musik, Theater und Tanz, sie sich an mehreren Standorten in Wien befindet (Hauptstandort: Johannesgasse 4a, 1010 Wien, [[Innere]] Stadt) und eine lange Tradition in der Ausbildung von Künstlern auf höchstem Niveau hat"}, {"kategorie": "", "text": "Im Jahr 2005 erhielt das Konservatorium den Status einer Privatuniversität und wurde in \"Konservatorium Wien Privatuniversität\" umbenannt. Im Jahr 2015 erfolgte eine weitere Umbenennung in \"Musik und Kunst Privatuniversität der Stadt Wien\" (MUK), um die Erweiterung des Angebots und die umfassendere künstlerische Ausbildung zu reflektieren."}]'::jsonb, ''),
  ('mdw', 'mdw', '', '', '', '', 'mdw', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Universität für Musik und darstellende Kunst Wien\" (früher: \"Hochschule für Musik und Darstellende Kunst\")"}, {"kategorie": "", "text": "eine der ältesten und renommiertesten Musikhochschulen der Welt. Sie befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]) und ist eine führende Institution für die Ausbildung in den Bereichen Musik, darstellende Kunst und Film"}, {"kategorie": "", "text": "Die Institution wurde 1817 als \"K.k. Konservatorium der Gesellschaft der Musikfreunde\" gegründet. Sie entwickelte sich rasch zu einem zentralen Ort für die Musikausbildung in Wien - der Stadt, die als eines der bedeutendsten Zentren der klassischen Musik gilt"}, {"kategorie": "", "text": "Im Laufe der Zeit wurde die Institution mehrfach umbenannt. Sie erhielt den Namen Hochschule für Musik und darstellende Kunst Wien in den 1970er Jahren. Seit 1998 trägt sie den Titel Universität für Musik und darstellende Kunst Wien (mdw)"}]'::jsonb, 'Universität fia Musik und doaschdöllende Kunst Wiin'),
