  ('schdeea', 'Schdeea', '', '', '', '', 'Steher', '[{"kategorie": "wörtlich", "text": "\"jemand, der alles durchsteht\", [[Stehaufmännchen]]"}, {"kategorie": "Bauwesen", "text": "Ständer, Pfosten, Stützpfosten (tragender senkrechter Balken bzw. tragende Säule)"}, {"kategorie": "Gaunersprache", "text": "Verhörter, der trotz Polizeidruck kein Geständnis ablegt bzw. dauerhaft schweigt"}, {"kategorie": "Sportlerjargon", "text": "Sportler (bzw. Rennpferd, etc.), der auf Langdistanzen seine besten Leistungen bringt"}, {"kategorie": "Fußballerjargon", "text": "Stehplatz, Stehplatzkarte"}]'::jsonb, ''),
