  ('schdaabeissa', 'Schdaabeissa', '', '', '', '', 'Steinbeißer', '[{"kategorie": "wörtlich", "text": "\"Steinbeißer\" (Determinativkompositum aus \"Stein\"=\"Strafvollzugsanstalt [[Stein]] an der Donau\" und \"Beißer\"=\"Gitterstäbebeißer\")"}, {"kategorie": "Gaunersprache, scherzhaft für", "text": "Mithäftling, Zellengenosse, [[Hääfnbruada]], [[Schdaanara]]"}, {"kategorie": "scherzhaft für", "text": "alter Bekannter, alter Weggefährte (aus der Strafvollzugsanstalt [[Stein]] an der Donau\")"}]'::jsonb, ''),
